-- test.close_backup: daily close integration evidence.
-- Access path: test schema indexes and scans.
SELECT JSON_OBJECT('tran_id' VALUE tran_id, 'account_id' VALUE account_id, 'account_sequence' VALUE account_sequence, 'amount' VALUE amount, 'balance_after' VALUE balance_after, 'inout_type' VALUE inout_type, 'tran_type' VALUE tran_type, 'print_content' VALUE print_content, 'counterparty_bank_code' VALUE counterparty_bank_code, 'counterparty_account_no' VALUE counterparty_account_no, 'counterparty_name' VALUE counterparty_name, 'channel' VALUE channel, 'terminal_id' VALUE terminal_id, 'request_id' VALUE request_id, 'transfer_id' VALUE transfer_id, 'reversal_of' VALUE reversal_of, 'business_date' VALUE TO_CHAR(business_date, 'YYYY-MM-DD'), 'occurred_at' VALUE TO_CHAR(occurred_at, 'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'), 'recorded_at' VALUE TO_CHAR(recorded_at, 'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM') RETURNING VARCHAR2(4000)) FROM account_transaction WHERE tran_id = :tran_id
